CREATE POLICY credential_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='credentials' AND (storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY credential_download ON storage.objects FOR SELECT TO authenticated USING(bucket_id='credentials' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));